export type OrderState = "received" | "validated" | "stored";

export interface Order {
  id: string;
  total: number;
}

export function validateOrder(order: Order): Order {
  if (!order.id || order.total < 0) throw new Error("Invalid order");
  return order;
}

export function storeOrder(order: Order, write: (order: Order) => void): void {
  write(validateOrder(order));
}
